Here is the commit message:
KVM: s390: pci: fix GAIT table indexing due to double-scaling
 pointer arithmetic

kvm_s390_pci_aif_enable(), kvm_s390_pci_aif_disable(), and
aen_host_forward() index the GAIT by manually multiplying the index
with sizeof(struct zpci_gaite).

Since aift->gait is already a struct zpci_gaite pointer, this
double-scales the offset, accessing element aisb*16 instead of aisb.

This causes out-of-bounds accesses when aisb >= 32 (with
ZPCI_NR_DEVICES=512)

Fix by removing the erroneous sizeof multiplication.

Fixes: 3c5a1b6f0a18 ("KVM: s390: pci: provide routines for enabling/disabling interrupt forwarding")
Fixes: 73f91b004321 ("KVM: s390: pci: enable host forwarding of Adapter Event Notifications")
Reported-by: Yuhao Jiang <danisjiang@gmail.com>
Cc: stable@vger.kernel.org
Signed-off-by: Junrui Luo <moonafterrain@outlook.com>
Reviewed-by: Christian Borntraeger <borntraeger@linux.ibm.com>
Reviewed-by: Matthew Rosato <mjrosato@linux.ibm.com>
Tested-by: Matthew Rosato <mjrosato@linux.ibm.com>
Signed-off-by: Christian Borntraeger <borntraeger@linux.ibm.com>

Here is the root cause:
The bug is a double-scaling error in pointer arithmetic when indexing into the GAIT (Global Adapter Interruption Table). The pointer `aift->gait` is already of type `struct zpci_gaite *`, so pointer arithmetic automatically multiplies the index by `sizeof(struct zpci_gaite)`. The original code explicitly multiplied the index by `sizeof(struct zpci_gaite)` again, resulting in an actual offset of `index * sizeof(struct zpci_gaite) * sizeof(struct zpci_gaite)`. This causes out-of-bounds reads/writes when the index is >= 32 (with ZPCI_NR_DEVICES=512), as the accessed memory is far beyond the allocated GAIT array.

Here is the patch:

 static int kvm_s390_pci_aif_enable(struct zpci_dev *zdev, struct zpci_fib *fib,
 				   bool assist)
 {
 	struct page *pages[1], *aibv_page, *aisb_page = NULL;
 	unsigned int msi_vecs, idx;
 	struct zpci_gaite *gaite;
 	unsigned long hva, bit;
 	struct kvm *kvm;
 	phys_addr_t gaddr;
 	int rc = 0, gisc, npages, pcount = 0;

 	/*
 	 * Interrupt forwarding is only applicable if the device is already
 	 * enabled for interpretation
 	 */
 	if (zdev->gisa == 0)
 		return -EINVAL;

 	kvm = zdev->kzdev->kvm;
 	msi_vecs = min_t(unsigned int, fib->fmt0.noi, zdev->max_msi);

 	/* Get the associated forwarding ISC - if invalid, return the error */
 	gisc = kvm_s390_gisc_register(kvm, fib->fmt0.isc);
 	if (gisc < 0)
 		return gisc;

 	/* Replace AIBV address */
 	idx = srcu_read_lock(&kvm->srcu);
 	hva = gfn_to_hva(kvm, gpa_to_gfn((gpa_t)fib->fmt0.aibv));
 	npages = pin_user_pages_fast(hva, 1, FOLL_WRITE | FOLL_LONGTERM, pages);
 	srcu_read_unlock(&kvm->srcu, idx);
 	if (npages < 1) {
 		rc = -EIO;
 		goto out;
 	}
 	aibv_page = pages[0];
 	pcount++;
 	gaddr = page_to_phys(aibv_page) + (fib->fmt0.aibv & ~PAGE_MASK);
 	fib->fmt0.aibv = gaddr;

 	/* Pin the guest AISB if one was specified */
 	if (fib->fmt0.sum == 1) {
 		idx = srcu_read_lock(&kvm->srcu);
 		hva = gfn_to_hva(kvm, gpa_to_gfn((gpa_t)fib->fmt0.aisb));
 		npages = pin_user_pages_fast(hva, 1, FOLL_WRITE | FOLL_LONGTERM,
 					     pages);
 		srcu_read_unlock(&kvm->srcu, idx);
 		if (npages < 1) {
 			rc = -EIO;
 			goto unpin1;
 		}
 		aisb_page = pages[0];
 		pcount++;
 	}

 	/* Account for pinned pages, roll back on failure */
 	if (account_mem(pcount))
 		goto unpin2;

 	/* AISB must be allocated before we can fill in GAITE */
 	mutex_lock(&aift->aift_lock);
 	bit = airq_iv_alloc_bit(aift->sbv);
 	if (bit == -1UL)
 		goto unlock;
 	zdev->aisb = bit; /* store the summary bit number */
 	zdev->aibv = airq_iv_create(msi_vecs, AIRQ_IV_DATA |
 				    AIRQ_IV_BITLOCK |
 				    AIRQ_IV_GUESTVEC,
 				    phys_to_virt(fib->fmt0.aibv));

 	spin_lock_irq(&aift->gait_lock);
-	gaite = (struct zpci_gaite *)aift->gait + (zdev->aisb *
-						   sizeof(struct zpci_gaite));
+	gaite = aift->gait + zdev->aisb;

 	/* If assist not requested, host will get all alerts */
 	if (assist)
 		gaite->gisa = (u32)virt_to_phys(&kvm->arch.sie_page2->gisa);
 	else
 		gaite->gisa = 0;

 	gaite->gisc = fib->fmt0.isc;
 	gaite->count++;
 	gaite->aisbo = fib->fmt0.aisbo;
 	gaite->aisb = virt_to_phys(page_address(aisb_page) + (fib->fmt0.aisb &
 							      ~PAGE_MASK));
 	aift->kzdev[zdev->aisb] = zdev->kzdev;
 	spin_unlock_irq(&aift->gait_lock);

 	/* Update guest FIB for re-issue */
 	fib->fmt0.aisbo = zdev->aisb & 63;
 	fib->fmt0.aisb = virt_to_phys(aift->sbv->vector + (zdev->aisb / 64) * 8);
 	fib->fmt0.isc = gisc;

 	/* Save some guest fib values in the host for later use */
 	zdev->kzdev->fib.fmt0.isc = fib->fmt0.isc;
 	zdev->kzdev->fib.fmt0.aibv = fib->fmt0.aibv;
 	mutex_unlock(&aift->aift_lock);

 	/* Issue the clp to setup the irq now */
 	rc = kvm_zpci_set_airq(zdev);
 	return rc;

 unlock:
 	mutex_unlock(&aift->aift_lock);
 unpin2:
 	if (fib->fmt0.sum == 1)
 		unpin_user_page(aisb_page);
 unpin1:
 	unpin_user_page(aibv_page);
 out:
 	return rc;
 }

 static int kvm_s390_pci_aif_disable(struct zpci_dev *zdev, bool force)
 {
 	struct kvm_zdev *kzdev = zdev->kzdev;
 	struct zpci_gaite *gaite;
 	struct page *vpage = NULL, *spage = NULL;
 	int rc, pcount = 0;
 	u8 isc;

 	if (zdev->gisa == 0)
 		return -EINVAL;

 	mutex_lock(&aift->aift_lock);

 	/*
 	 * If the clear fails due to an error, leave now unless we know this
 	 * device is about to go away (force) -- In that case clear the GAITE
 	 * regardless.
 	 */
 	rc = kvm_zpci_clear_airq(zdev);
 	if (rc && !force)
 		goto out;

 	if (zdev->kzdev->fib.fmt0.aibv == 0)
 		goto out;
 	spin_lock_irq(&aift->gait_lock);
-	gaite = (struct zpci_gaite *)aift->gait + (zdev->aisb *
-						   sizeof(struct zpci_gaite));
+	gaite = aift->gait + zdev->aisb;
 	isc = gaite->gisc;
 	gaite->count--;
 	if (gaite->count == 0) {
 		/* Release guest AIBV and AISB */
 		vpage = phys_to_page(kzdev->fib.fmt0.aibv);
 		if (gaite->aisb != 0)
 			spage = phys_to_page(gaite->aisb);
 		/* Clear the GAIT entry */
 		gaite->aisb = 0;
 		gaite->gisc = 0;
 		gaite->aisbo = 0;
 		gaite->gisa = 0;
 		aift->kzdev[zdev->aisb] = NULL;
 		/* Clear zdev info */
 		airq_iv_free_bit(aift->sbv, zdev->aisb);
 		airq_iv_release(zdev->aibv);
 		zdev->aisb = 0;
 		zdev->aibv = NULL;
 	}
 	spin_unlock_irq(&aift->gait_lock);
 	kvm_s390_gisc_unregister(kzdev->kvm, isc);
 	kzdev->fib.fmt0.isc = 0;
 	kzdev->fib.fmt0.aibv = 0;

 	if (vpage) {
 		unpin_user_page(vpage);
 		pcount++;
 	}
 	if (spage) {
 		unpin_user_page(spage);
 		pcount++;
 	}
 	if (pcount > 0)
 		unaccount_mem(pcount);
 out:
 	mutex_unlock(&aift->aift_lock);

 	return rc;
 }



